 -- 1. SQL DATABASE & ANALYSIS
-- 1.1 Create the database
USE ecommerce_churn;
TRUNCATE TABLE customers;
-- 1.2 Insert the table values



-- 1.3 Check total customers
SELECT COUNT(*) AS Total_Customers FROM customers;
-- 1.4 View data
SELECT * FROM customers LIMIT 10;
-- 1.5 Check churn
SELECT Churn_Status, COUNT(*) AS Customers
FROM customers
GROUP BY Churn_Status;
-- 1.6 Calculate churn rate
SELECT 
    ROUND(AVG(Churn) * 100, 2) AS Churn_Rate
FROM customers;
-- 1.7 Average spending
SELECT 
    ROUND(AVG(Total_Spend), 2) AS Average_Spend
FROM customers;
-- 2. Business analysis queries
-- 2.1 Top 10 customers by spending
SELECT Customer_ID, Total_Spend
FROM customers
ORDER BY Total_Spend DESC
LIMIT 10;
-- 2.2 City-wise churn
SELECT 
    City,
    COUNT(*) AS Customers,
    SUM(Churn) AS Churned_Customers,
    ROUND(AVG(Churn) * 100, 2) AS Churn_Rate
FROM customers
GROUP BY City
ORDER BY Churn_Rate DESC;
-- 2.3 Churn by gender
SELECT 
    Gender,
    COUNT(*) AS Customers,
    SUM(Churn) AS Churned_Customers,
    ROUND(AVG(Churn) * 100, 2) AS Churn_Rate
FROM customers
GROUP BY Gender;
-- 2.4 Churn by purchase frequency
SELECT
    CASE
        WHEN Total_Orders <= 3 THEN 'Low'
        WHEN Total_Orders <= 10 THEN 'Medium'
        ELSE 'High'
    END AS Purchase_Frequency,
    COUNT(*) AS Customers,
    ROUND(AVG(Churn) * 100, 2) AS Churn_Rate
FROM customers
GROUP BY Purchase_Frequency
ORDER BY Churn_Rate DESC;
-- 2.5 High-value customers at risk
SELECT
    Customer_ID,
    Total_Spend,
    Total_Orders,
    Days_Since_Last_Purchase,
    Churn_Status
FROM customers
WHERE Total_Spend >= 5000
AND Churn = 1
ORDER BY Total_Spend DESC;